                crossAxisAlignment: cruftfreeCrossAxis(resolved?.align, CrossAxisAlignment.start),
                spacing: gap,
                children: [for (var column = 0; column < columns; column++) Expanded(child: start + column < children.length ? children[start + column] : const SizedBox.shrink())],
              ),
          ],
        );
      },
    );
    return cruftfreeStyled(context, style, grid, paint);
  }
}

/// A container's optional title, announced as a header.
class _Title extends StatelessWidget {
  const _Title(this.text, this.textStyle);

  final String text;
  final TextStyle? textStyle;

  @override
  Widget build(BuildContext context) {
    return Semantics(
      header: true,
      child: Text(text, style: textStyle?.copyWith(fontWeight: FontWeight.w600)),
    );
  }
}

/// A titled container's header: its title and, at the trailing edge, the
/// actions flagged `headerAction`.
class _Header extends StatelessWidget {
  const _Header(this.text, this.textStyle, this.actions);

  final String text;
  final TextStyle? textStyle;
  final List<Widget> actions;

  @override
  Widget build(BuildContext context) {
    final title = _Title(text, textStyle);
    if (actions.isEmpty) {
      return title;
    }
    return Row(
      crossAxisAlignment: CrossAxisAlignment.center,
      spacing: CruftFreeTokens.of(context).gap,
      children: [
        Expanded(child: title),
        ...actions,
      ],
    );
  }
}

/// `card(title?) { ... }`: a raised surface holding its children; a titled
/// card draws its [headerActions] beside the title. A [paint] fills the card's own surface and
/// draws its outline; its text colour and opacity apply to the whole card.
class CruftFreeCard extends StatelessWidget {
  const CruftFreeCard({super.key, this.title, this.headerActions = const [], this.linkLabel, this.onPressed, this.style, this.paint, required this.children});

  final String? title;
  final List<Widget> headerActions;

  /// `: to(Page)`, `: url(address)` or `: configured(name)`: the whole card is one link, named by
  /// [linkLabel] (the card's title) and running [onPressed] when it is activated.
  final String? linkLabel;
  final VoidCallback? onPressed;
  final CruftFreeStyle? style;
  final CruftFreePaint? paint;
  final List<Widget> children;

  @override
  Widget build(BuildContext context) {
    final tokens = CruftFreeTokens.of(context);
    final heading = title;
    final painted = paint;
    final content = Padding(
      padding: EdgeInsets.all(tokens.inset),
      child: CruftFreeStack(style: style, children: [if (heading != null) _Header(heading, cruftfreeScaledPart(Theme.of(context).textTheme.titleMedium, cruftfreeFontScale(context, style)), headerActions), ...children]),
    );
    final shape = cruftfreePaintedOutline(Theme.of(context).cardTheme.shape, painted?.borderColor);
    final target = onPressed;
    final Widget card;
    if (target == null) {
      card = Card(color: painted?.background, shape: shape, child: content);
    } else {
      card = _linkSurface(
        label: linkLabel,
        child: Card(
          color: painted?.background,
          shape: shape,
          clipBehavior: Clip.antiAlias,
          child: InkWell(onTap: target, child: content),
        ),
      );
    }
    return cruftfreeStyled(context, null, card, painted?.drawnAround(outline: true));
  }
}

/// A container that is one link as a whole: announced as a link named by [label]. The surface it
/// wraps draws the hover and focus treatment of an interactive surface (an `InkWell`).
Widget _linkSurface({required String? label, required Widget child}) {
  return Semantics(link: true, container: true, label: label, child: child);
}

/// `section(title?) { ... }`: a titled group of its children, announced as
/// one; a titled section draws its [headerActions] beside the title.
class CruftFreeSection extends StatelessWidget {
  const CruftFreeSection({super.key, this.title, this.headerActions = const [], this.linkLabel, this.onPressed, this.style, this.paint, required this.children});

  final String? title;
  final List<Widget> headerActions;

  /// `: to(Page)`, `: url(address)` or `: configured(name)`: the whole section is one link, named
  /// by [linkLabel] (the section's title) and running [onPressed] when it is activated.
  final String? linkLabel;
  final VoidCallback? onPressed;
  final CruftFreeStyle? style;
  final CruftFreePaint? paint;
  final List<Widget> children;

  @override
  Widget build(BuildContext context) {
    final heading = title;
    final content = CruftFreeStack(style: style, paint: paint, children: [if (heading != null) _Header(heading, cruftfreeScaledPart(Theme.of(context).textTheme.titleLarge, cruftfreeFontScale(context, style)), headerActions), ...children]);
    final target = onPressed;
    if (target == null) {
      return Semantics(container: true, explicitChildNodes: true, child: content);
    }
    return _linkSurface(
      label: linkLabel,
      child: InkWell(onTap: target, child: content),
    );
  }
}

/// `section(title) : collapsible { ... }`: a titled group whose children the reader shows and hides
/// by activating the title (a tap, or Enter and Space with the title focused), collapsed unless
/// [open]. Each instance keeps its own state, so one built per item of a loop opens on its own, and
/// the platform exposes the expanded or collapsed state of the title to assistive technology. A
/// disclosure's [headerActions] lead its children, since a title that is a control holds no other.
class CruftFreeDisclosure extends StatelessWidget {
  const CruftFreeDisclosure({super.key, required this.title, this.open = false, this.headerActions = const [], this.style, this.paint, required this.children});

  final String title;
  final bool open;
  final List<Widget> headerActions;
  final CruftFreeStyle? style;
  final CruftFreePaint? paint;
  final List<Widget> children;

  @override
  Widget build(BuildContext context) {
    final tile = ExpansionTile(
      title: Text(title, style: cruftfreeScaledPart(Theme.of(context).textTheme.titleLarge, cruftfreeFontScale(context, style))),
      initiallyExpanded: open,
      controlAffinity: ListTileControlAffinity.leading,
      expandedCrossAxisAlignment: CrossAxisAlignment.stretch,
      expandedAlignment: Alignment.centerLeft,
      children: [
        if (headerActions.isNotEmpty) Wrap(spacing: 8, children: headerActions),
        ...children,
      ],
    );
    return cruftfreeStyled(context, style, Semantics(container: true, explicitChildNodes: true, child: tile), paint);
  }
}

/// One `tab(label) { ... }` of a `tabs`: its label, what selecting it runs,
/// and the content shown while it is selected. A tab of a bound `tabs`
/// carries its [value] (the key the selection holds); [badge] is a count
/// shown beside the label.
class CruftFreeTab {
  const CruftFreeTab({required this.label, this.value, this.badge, this.onSelected, this.children = const []});

  final String label;
  final String? value;
  final String? badge;
  final VoidCallback? onSelected;
  final List<Widget> children;
}

/// `tabs { tab(...) { ... } ... }`: a tab bar over the selected tab's
/// content. A bound `tabs` shows the tab whose value [selected] holds and
/// reports the tab the user picks through [onChanged]; one that binds
/// nothing keeps its own selection.
class CruftFreeTabs extends StatefulWidget {
  const CruftFreeTabs({super.key, this.style, this.selected, this.onChanged, required this.tabs});

  final CruftFreeStyle? style;
  final String? selected;
  final ValueChanged<String>? onChanged;
  final List<CruftFreeTab> tabs;

  @override
  State<CruftFreeTabs> createState() => _CruftFreeTabsState();
}

class _CruftFreeTabsState extends State<CruftFreeTabs> with SingleTickerProviderStateMixin {
  late TabController _controller;

  int _indexOf(String? value) {
    final index = widget.tabs.indexWhere((tab) => tab.value != null && tab.value == value);
    return index < 0 ? 0 : index;
  }

  void _create() {
    _controller = TabController(length: widget.tabs.length, vsync: this, initialIndex: _indexOf(widget.selected));
  }

  @override
  void initState() {
    super.initState();
    _create();
  }

  @override
  void didUpdateWidget(CruftFreeTabs oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.tabs.length != widget.tabs.length) {
      _controller.dispose();
      _create();
      return;
    }
    final index = _indexOf(widget.selected);
    if (widget.selected != null && index != _controller.index) {
      _controller.animateTo(index);
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  void _picked(int index) {
    final tab = widget.tabs[index];
    final value = tab.value;
    if (value != null) {
      widget.onChanged?.call(value);
    }
    tab.onSelected?.call();
  }

  @override
  Widget build(BuildContext context) {
    final tabs = widget.tabs;
    if (tabs.isEmpty) {
      return const SizedBox.shrink();
    }
    final content = Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      spacing: CruftFreeTokens.of(context).gap,
      children: [
        TabBar(
          controller: _controller,
          isScrollable: true,
          tabs: [for (final tab in tabs) Tab(child: _TabLabel(tab))],
          onTap: _picked,
        ),
        ListenableBuilder(
          listenable: _controller,
          builder: (context, _) => CruftFreeStack(children: tabs[_controller.index].children),
        ),
      ],
    );
    return cruftfreeStyled(context, widget.style, content);
  }
}

/// A tab's label and, beside it, its count badge; announced as one label.
class _TabLabel extends StatelessWidget {
  const _TabLabel(this.tab);

  final CruftFreeTab tab;

  @override
  Widget build(BuildContext context) {
    final count = tab.badge;
    if (count == null) {
      return Text(tab.label);
    }
    return Semantics(
      label: '${tab.label} $count',
      excludeSemantics: true,
      child: Row(
        mainAxisSize: MainAxisSize.min,
        spacing: CruftFreeTokens.of(context).gap / 2,
        children: [
          Text(tab.label),
          Badge(label: Text(count)),
        ],
      ),
    );
  }
}

/// A length a modifier is written in (`max(12rows)`, `max(400px)`): whole logical pixels, or
/// whole rows of text. One row is the line height of the text style in effect at the device's
/// text scale, so a cap in rows grows with the text size the reader chose.
class CruftFreeModifierLength {
  const CruftFreeModifierLength.pixels(this.magnitude) : rows = false;
  const CruftFreeModifierLength.rows(this.magnitude) : rows = true;

  final int magnitude;
  final bool rows;

  /// This length in logical pixels where [context] is laid out.
  double resolve(BuildContext context) {
    if (!rows) {
      return magnitude.toDouble();
    }
    final painter = TextPainter(
      text: TextSpan(text: ' ', style: DefaultTextStyle.of(context).style),
      textDirection: Directionality.of(context),
      textScaler: MediaQuery.textScalerOf(context),
    );
    final row = painter.preferredLineHeight;
    painter.dispose();
    return magnitude * row;
  }
}

/// `scroll { ... }`: a region scrolling its children, reachable and
/// scrollable from the keyboard. `scroll : max(...)` caps its height at [max]
/// (never more than its container gives it) and scrolls the rest; a table
/// inside a capped region keeps its heading row in view ([CruftFreeTableSurface]).
class CruftFreeScroll extends StatelessWidget {
  const CruftFreeScroll({super.key, this.style, this.max, required this.children});

  final CruftFreeStyle? style;
  final CruftFreeModifierLength? max;
  final List<Widget> children;

  @override
  Widget build(BuildContext context) {
    final cap = max;
    final region = LayoutBuilder(
      builder: (context, constraints) {
        final room = constraints.hasBoundedHeight ? constraints.maxHeight : null;
        final height = cap == null ? room ?? MediaQuery.sizeOf(context).height * _scrollViewportShare : math.min(room ?? double.infinity, cap.resolve(context));
        final content = CruftFreeStack(children: children);
        return ConstrainedBox(
          constraints: BoxConstraints(maxHeight: height),
          child: Focus(
            child: Scrollbar(
              child: SingleChildScrollView(child: cap == null ? content : _CruftFreeCappedScroll(child: content)),
            ),
          ),
        );
      },
    );
    return cruftfreeStyled(context, style, region);
  }
}

/// Marks the content of a capped `scroll`: a table inside it keeps its heading row in view
/// while its rows scroll beneath.
class _CruftFreeCappedScroll extends InheritedWidget {
  const _CruftFreeCappedScroll({required super.child});

  static bool holds(BuildContext context) => context.dependOnInheritedWidgetOfExactType<_CruftFreeCappedScroll>() != null;

  @override
  bool updateShouldNotify(_CruftFreeCappedScroll oldWidget) => false;
}

/// `spacer`: the theme's gap as empty space, never announced.
class CruftFreeSpacer extends StatelessWidget {
  const CruftFreeSpacer({super.key, this.style});

  final CruftFreeStyle? style;

  @override
  Widget build(BuildContext context) {
    return cruftfreeStyled(context, style, SizedBox.square(dimension: CruftFreeTokens.of(context).gap));
  }
}

/// `divider`: a one-pixel rule in the theme's line colour across its
/// container, with no space of its own -- its container's gap spaces it, as
/// it does every other child. A row draws it vertical ([_CruftFreeRunRule]).
class CruftFreeDivider extends StatelessWidget {
  const CruftFreeDivider({super.key, this.style});

  final CruftFreeStyle? style;

  @override
  Widget build(BuildContext context) {
    return cruftfreeStyled(context, style, Divider(height: 1, thickness: 1, indent: 0, endIndent: 0, color: cruftfreeLineColor(context)));
  }
}

/// A `divider` standing directly in a row: a one-pixel vertical rule in the
/// theme's line colour, as tall as the row's run it stands in.
class _CruftFreeRunRule extends StatelessWidget {
  const _CruftFreeRunRule({super.key, this.style});

  final CruftFreeStyle? style;

  @override
  Widget build(BuildContext context) {
    final rule = VerticalDivider(width: 1, thickness: 1, indent: 0, endIndent: 0, color: cruftfreeLineColor(context));
    return _CruftFreeSpansRun(child: cruftfreeStyled(context, style, rule));
  }
}

/// Marks a row's child as spanning the height of its run ([_RenderCruftFreeWrap]).
class _CruftFreeSpansRun extends ParentDataWidget<_CruftFreeWrapParentData> {
  const _CruftFreeSpansRun({required super.child});

  @override
  void applyParentData(RenderObject renderObject) {
    final data = renderObject.parentData! as _CruftFreeWrapParentData;
    if (!data.spansRun) {
      data.spansRun = true;
      renderObject.parent?.markNeedsLayout();
    }
  }

  @override
  Type get debugTypicalAncestorWidgetClass => _CruftFreeWrap;
}

/// How a modal element is presented.
enum CruftFreeModalKind { dialog, drawer, sheet }

/// `dialog`/`drawer`/`sheet { ... }`: shown as a modal route while the
/// element is in the view -- focus is trapped inside it and restored when it
/// closes. Dismissing it closes it and runs `onClose` (`: onClose(...)`), where
/// the state showing it learns it closed; it opens again when the view shows
/// the element again. The view no longer showing it closes it without `onClose`.
class CruftFreeModal extends StatefulWidget {
  const CruftFreeModal({super.key, required this.kind, this.title, this.style, this.onClose, this.alert = false, required this.children});

  final CruftFreeModalKind kind;
  final String? title;
  final CruftFreeStyle? style;
  final VoidCallback? onClose;

  /// `alert`: announced as an alert dialog (a confirmation that interrupts), not a plain dialog.
  final bool alert;
  final List<Widget> children;

  @override
  State<CruftFreeModal> createState() => _CruftFreeModalState();
}

class _CruftFreeModalState extends State<CruftFreeModal> {
  late final ValueNotifier<CruftFreeModal> _shown = ValueNotifier<CruftFreeModal>(widget);
  Route<void>? _route;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => _open());
  }

  @override
  void didUpdateWidget(CruftFreeModal oldWidget) {
    super.didUpdateWidget(oldWidget);
    _shown.value = widget;
  }

  void _open() {
    if (!mounted) {
      return;
    }
    final navigator = Navigator.of(context, rootNavigator: true);
    final themes = InheritedTheme.capture(from: context, to: navigator.context);
    final label = MaterialLocalizations.of(context).modalBarrierDismissLabel;
    final route = switch (widget.kind) {
      CruftFreeModalKind.dialog => DialogRoute<void>(
        context: context,
        themes: themes,
        barrierLabel: label,
        builder: (context) => Dialog(child: _content(context)),
      ),
      CruftFreeModalKind.sheet => ModalBottomSheetRoute<void>(
        capturedThemes: themes,
        barrierLabel: label,
        isScrollControlled: true,
        builder: (context) => SafeArea(child: _content(context)),
      ),
      CruftFreeModalKind.drawer => RawDialogRoute<void>(
        barrierDismissible: true,
        barrierLabel: label,
        barrierColor: Theme.of(context).colorScheme.scrim.withValues(alpha: 0.32),
        pageBuilder: (context, animation, secondaryAnimation) => themes.wrap(
          Align(
            alignment: AlignmentDirectional.centerStart,
            child: Drawer(child: SafeArea(child: _content(context))),
          ),
        ),
        transitionBuilder: (context, animation, secondaryAnimation, child) => SlideTransition(
          position: Tween<Offset>(begin: const Offset(-1, 0), end: Offset.zero).animate(animation),
          child: child,
        ),
      ),
    };
    _route = route;
    unawaited(navigator.push(route).whenComplete(_closed));
  }

  /// The route is gone: dismissed by the person while the view still shows the
  /// element (`onClose` runs), or removed because the view stopped showing it
  /// (the state is disposed by then, and nothing runs).
  void _closed() {
    _route = null;
    if (mounted) {
      widget.onClose?.call();
    }
  }

  Widget _content(BuildContext context) {
    return ValueListenableBuilder<CruftFreeModal>(
      valueListenable: _shown,
      builder: (context, modal, _) {
        final title = modal.title;
        return Semantics(
          scopesRoute: true,
          namesRoute: title != null,
          label: title,
          role: modal.alert ? SemanticsRole.alertDialog : SemanticsRole.none,
          explicitChildNodes: true,
          child: SingleChildScrollView(
            padding: EdgeInsets.all(CruftFreeTokens.of(context).inset),
            child: CruftFreeStack(style: modal.style, children: [if (title != null) _Title(title, Theme.of(context).textTheme.titleLarge), ...modal.children]),
          ),
        );
      },
    );
  }

  @override
  void dispose() {
    final route = _route;
    if (route != null && route.isActive) {
      route.navigator?.removeRoute(route);
    }
    _shown.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => const SizedBox.shrink();
}

/// One `menuItem(label) : onClick(...)` of a `menu`: pressing it runs its
/// action and the enclosing anchor closes the menu.
///
/// `checked(c)` marks the item as the menu's current choice: a check mark leads its label (a
/// reserved gap while it is not checked, so the labels stay aligned) and it is announced as
/// checked -- as a choice of a group of exclusive items, or, with [multiple], as a toggle of its
/// own.
class CruftFreeMenuItem extends StatelessWidget {
  const CruftFreeMenuItem({super.key, this.style, required this.label, this.onSelected, this.enabled = true, this.checked, this.multiple = false, this.children = const []});

  final CruftFreeStyle? style;
  final String label;
  final VoidCallback? onSelected;
  final bool enabled;
  final bool? checked;
  final bool multiple;
  final List<Widget> children;

  @override
  Widget build(BuildContext context) {
    final current = checked;
    final item = MenuItemButton(
      onPressed: enabled ? onSelected : null,
      leadingIcon: current == null ? null : ExcludeSemantics(child: Icon(Icons.check, size: 20, color: current ? null : Colors.transparent)),
      child: children.isEmpty ? Text(label) : CruftFreeStack(children: [Text(label), ...children]),
    );
    final marked = current == null ? item : Semantics(checked: current, inMutuallyExclusiveGroup: !multiple, child: item);
    return cruftfreeStyled(context, style, marked);
  }
}

/// A `link(...)` or `externalLink(...)` row of a `menu` panel: an item of the panel like a
/// [CruftFreeMenuItem] -- the arrow keys move to it and pressing it closes the menu -- that then opens
/// its destination. Its icon leads its label, and its `description(Msg)` is a second, quieter
/// line under the label. Announced as a link; while [enabled] is false it opens nothing.
class CruftFreeMenuLink extends StatelessWidget {
  const CruftFreeMenuLink({super.key, this.style, required this.label, required this.onPressed, this.icon, this.description, this.enabled = true, this.autofocus = false, this.opensNewTab = false});

  final CruftFreeStyle? style;
  final String label;
  final VoidCallback onPressed;
  final IconData? icon;
  final String? description;
  final bool enabled;

  /// The row opens a new tab (`externalLink : newTab`): its hint says so and a glyph follows its label
  /// while the theme draws one.
  final bool opensNewTab;

  /// `initialFocus`: has focus when the route that shows it opens.
  final bool autofocus;

  @override
  Widget build(BuildContext context) {
    final glyph = icon;
    final second = description;
    final theme = Theme.of(context);
    final item = MenuItemButton(
      onPressed: enabled ? onPressed : null,
      autofocus: autofocus,
      leadingIcon: glyph == null ? null : Icon(glyph),
      child: second == null || second.isEmpty
          ? _withNewTabGlyph(context, Text(label), opensNewTab: opensNewTab)
          : Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                _withNewTabGlyph(context, Text(label), opensNewTab: opensNewTab),
                Text(second, style: theme.textTheme.bodySmall?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
              ],
            ),
    );
    return cruftfreeStyled(context, style, Semantics(link: true, hint: opensNewTab ? cruftfreeNewTabWords() : null, child: item));
  }
}

/// `menu(name?) { <trigger> ... }`: the trigger child is the always-visible
/// control, which opens and closes the panel of the other children. Escape
/// and a tap outside close it, and the arrow keys move between its items.
class CruftFreeMenu extends StatelessWidget {
  const CruftFreeMenu({super.key, this.style, this.semanticLabel, required this.trigger, required this.children});

  final CruftFreeStyle? style;
  final String? semanticLabel;
  final Widget trigger;
  final List<Widget> children;

  @override
  Widget build(BuildContext context) {
    final menu = MenuAnchor(
      menuChildren: children,
      builder: (context, controller, child) => Semantics(
        button: true,
        expanded: controller.isOpen,
        label: semanticLabel,
        child: InkWell(onTap: () => controller.isOpen ? controller.close() : controller.open(), child: trigger),
      ),
    );
    return cruftfreeStyled(context, style, menu);
  }
}

/// `heading(text)`: announced as a header. With a [level] (`level(n)`, 1 to 6) it is announced
/// as a header of that level, as the web draws it as `h1` to `h6`; the look is the style's.
class CruftFreeHeading extends StatelessWidget {
  const CruftFreeHeading({super.key, required this.text, this.level, this.style, this.paint});

  final String text;
  final int? level;
  final CruftFreeStyle? style;
  final CruftFreePaint? paint;

  @override
  Widget build(BuildContext context) {
    final resolved = style?.resolve(context);
    final textStyle = Theme.of(context).textTheme.headlineSmall?.merge(resolved?.font).copyWith(color: paint?.color ?? resolved?.foreground?.call(context));
    return cruftfreeStyled(
      context,
      style,
      Semantics(
        header: true,
        headingLevel: level,
        child: Text(text, style: textStyle),
      ),
      paint,
    );
  }
}

/// `text(value)`: the value's text. As on the web, white space collapses -- a run of spaces and
/// line breaks is one space -- unless `preserveLines` keeps the value's line breaks and spacing
/// (long lines still wrap).
class CruftFreeText extends StatelessWidget {
  const CruftFreeText({super.key, required this.text, this.preserveLines = false, this.style, this.paint});

  final String text;
  final bool preserveLines;
  final CruftFreeStyle? style;
  final CruftFreePaint? paint;

  static final RegExp _whiteSpace = RegExp(r'\s+');

  @override
  Widget build(BuildContext context) => cruftfreeStyled(context, style, Text(preserveLines ? text : text.replaceAll(_whiteSpace, ' ')), paint);
}

/// `code(value)`: the value verbatim, in a monospace face, keeping its spaces and line breaks.
/// It never wraps: a line wider than the space scrolls sideways. The text is plain text, so
/// markup in the value is shown as it is written.
class CruftFreeCode extends StatelessWidget {
  const CruftFreeCode({super.key, required this.text, this.style, this.paint});

  final String text;
  final CruftFreeStyle? style;
  final CruftFreePaint? paint;

  @override
  Widget build(BuildContext context) {
    final body = SingleChildScrollView(
      scrollDirection: Axis.horizontal,
      child: Text(
        text,
        softWrap: false,
        style: const TextStyle(fontFamily: 'monospace', fontFamilyFallback: ['Courier New', 'Courier']),
      ),
    );
    return cruftfreeStyled(context, style, Semantics(container: true, child: body), paint);
  }
}

/// The colours of [tone], or the theme's neutral container colours.
CruftFreeTone _toneColors(BuildContext context, String? tone) {
  if (tone != null) {
    return CruftFreeTokens.of(context).tone(tone);
  }
  final scheme = Theme.of(context).colorScheme;
  return CruftFreeTone(background: scheme.secondaryContainer, foreground: scheme.onSecondaryContainer);
}

/// `badge(value) : tone(t)?, paint(...)?`: the value on a pill in its tone's colours; a painted
/// surface or text colour beats the tone's.
class CruftFreeBadge extends StatelessWidget {
  const CruftFreeBadge({super.key, required this.text, this.tone, this.style, this.paint});

  final String text;
  final String? tone;
  final CruftFreeStyle? style;
  final CruftFreePaint? paint;

  @override
  Widget build(BuildContext context) {
    final colors = _toneColors(context, tone);
    final painted = paint;
    final gap = CruftFreeTokens.of(context).gap;
    final pill = DecoratedBox(
      decoration: ShapeDecoration(shape: const StadiumBorder(), color: painted?.background ?? colors.background),
      child: Padding(
        padding: EdgeInsets.symmetric(horizontal: gap, vertical: gap / 2),
        child: Text(text, style: cruftfreeScaledPart(Theme.of(context).textTheme.labelMedium, cruftfreeFontScale(context, style))?.copyWith(color: painted?.color ?? colors.foreground)),
      ),
    );
    return cruftfreeStyled(context, style, Align(alignment: AlignmentDirectional.centerStart, widthFactor: 1, child: pill), painted?.drawnAround());
  }
}

/// The colours of the framework's own failure surface: the theme's `danger`
/// tone when it declares one, else the Material error colours -- a theme that
/// declares no `danger` still draws every derived error.
CruftFreeTone _failureColors(BuildContext context) {
  final danger = CruftFreeTokens.of(context).tones['danger'];
  if (danger != null) {
    return danger;
  }
  final scheme = Theme.of(context).colorScheme;
  return CruftFreeTone(background: scheme.errorContainer, foreground: scheme.onErrorContainer);
}

/// `callout(text) : tone(t)?, icon(name)? { <actions> }`: a banner -- an
/// icon, the text and, at the trailing edge, its [actions] -- on its tone's
/// surface, announced when it appears or changes. The framework's own error
/// state is this same widget (a [failure] callout with the problem's
/// [detail] and a retry), so a hand-built banner and a derived one cannot
/// drift. A [card]-sized one takes the surface of a card. A [paint] beats the tone's surface and
/// text colours, and draws the banner's outline.
class CruftFreeCallout extends StatelessWidget {
  const CruftFreeCallout({super.key, required this.text, this.detail, this.tone, this.failure = false, this.icon, this.actions = const [], this.card = false, this.style, this.paint});

  final String text;
  final String? detail;
  final String? tone;

  /// Whether it is the framework's failure surface (the `danger` tone, or the
  /// Material error colours when the theme declares none) rather than a tone.
  final bool failure;
  final IconData? icon;
  final List<Widget> actions;
  final bool card;
  final CruftFreeStyle? style;
  final CruftFreePaint? paint;

  @override
  Widget build(BuildContext context) {
    final toned = failure ? _failureColors(context) : _toneColors(context, tone);
    final painted = paint;
    final colors = CruftFreeTone(background: painted?.background ?? toned.background, foreground: painted?.color ?? toned.foreground);
    final outline = painted?.borderColor;
    final tokens = CruftFreeTokens.of(context);
    final more = detail;
    final message = Expanded(
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            text,
            style: TextStyle(color: colors.foreground, fontWeight: more == null ? null : FontWeight.w600),
          ),
          if (more != null && more.isNotEmpty) Text(more, style: TextStyle(color: colors.foreground)),
        ],
      ),
    );
    final callout = Semantics(
      liveRegion: true,
      container: true,
      child: DecoratedBox(
        decoration: BoxDecoration(
          color: colors.background,
          border: outline == null ? null : Border.all(color: outline),
          borderRadius: BorderRadius.circular(card ? tokens.radius * 1.5 : tokens.radius),
        ),
        child: Padding(
          padding: EdgeInsets.all(tokens.inset),
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            spacing: tokens.gap,
            children: [
              ExcludeSemantics(child: Icon(icon ?? Icons.info_outline, color: colors.foreground)),
              message,
              if (actions.isNotEmpty) Wrap(spacing: tokens.gap, runSpacing: tokens.gap, children: actions),
            ],
          ),
        ),
      ),
    );
    return cruftfreeStyled(context, style, callout, painted?.drawnAround(outline: true));
  }
}

/// The derived loading state: a spinner and its caption, announced as busy.
class CruftFreeLoadingState extends StatelessWidget {
  const CruftFreeLoadingState({super.key, this.card = false});

  /// Whether it replaces one card, section or table (rather than the page).
  final bool card;

  @override
  Widget build(BuildContext context) {
    final caption = cruftfreeRuntime.messages.key('framework.loading').text;
    final body = Padding(
      padding: EdgeInsets.all(CruftFreeTokens.of(context).inset),
      child: Center(child: CircularProgressIndicator(semanticsLabel: caption)),
    );
    return Semantics(
      label: caption,
      liveRegion: true,
      child: card ? Card(child: body) : body,
    );
  }
}

/// The derived error state: the danger-toned [CruftFreeCallout] an author composes
/// -- the problem's title and detail, a retry at the trailing edge. An error
/// is never drawn as an empty state.
class CruftFreeErrorState extends StatelessWidget {
  const CruftFreeErrorState({super.key, required this.failure, required this.onRetry, this.card = false, this.site, this.pausedForMs = 0});

  /// The failed load: its problem's title and detail (what the server marks
  /// displayable -- never a stack, URL or credential) are shown, or the
  /// framework's text for a response no problem body describes
  /// ([problemTitleText]); a failure that is no response shows the
  /// framework's own failure text.
  final Object failure;
  final VoidCallback? onRetry;

  /// Whether it replaces one card, section or table (rather than the page).
  final bool card;

  /// What the failed read is worded about: when the app's strings word the
  /// failure (`readFailed.<kind>`), that text replaces the title and detail
  /// -- it places `{detail}` itself. Without such text, or a site, the
  /// failure is drawn as its problem describes it.
  final ReadSite? site;

  /// The milliseconds left of the pause a rate-limited read started on the
  /// binding the retry refreshes (`SyncedBinding.pausedForMs`); 0 when none.
  /// While it is above 0 the retry is disabled and shows the time left.
  final int pausedForMs;

  @override
  Widget build(BuildContext context) {
    final messages = cruftfreeRuntime.messages;
    final problem = failure is CruftFreeException ? (failure as CruftFreeException).problem : null;
    final worded = readFailureText(problem ?? ProblemDetails.decode(null, ProblemDetails.noResponseStatus, null), messages, site);
    return CruftFreeCallout(
      text: worded ?? (problem == null ? messages.key('framework.failed').text : problemTitleText(problem, messages)),
      detail: worded == null ? problem?.detail : null,
      failure: true,
      icon: Icons.error_outline,
      card: card,
      actions: [FilledButton(onPressed: pausedForMs > 0 ? null : onRetry, child: Text(_retryText(pausedForMs, messages)))],
    );
  }
}

/// A retry's text: the framework's retry text, or -- while its binding is
/// paused by a rate-limited read -- the whole seconds left ([retryInText]).
String _retryText(int pausedForMs, Messages messages) {
  return pausedForMs > 0 ? retryInText(pausedForMs, messages) : messages.key('framework.retry').text;
}

/// The derived stale-data state: data a view loaded stays shown after a
/// refresh of it failed, under this notice -- a [CruftFreeCallout] in no tone
/// (informational, never an error), the refresh-failed text with the problem's
/// title, and a retry ([onRetry] is `null` while a request is in flight).
class CruftFreeStaleState extends StatelessWidget {
  const CruftFreeStaleState({super.key, required this.failure, required this.onRetry, this.card = false, this.site, this.pausedForMs = 0});

  /// The failed refresh: its problem's title is shown; a failure no problem
  /// describes shows the framework's own failure text.
  final Object failure;
  final VoidCallback? onRetry;

  /// Whether it sits in one card, section, menu panel or table (rather than the page).
  final bool card;

  /// What the failed refresh is worded about: the app's text for the failure, when its strings set one, replaces the problem's title.
  final ReadSite? site;

  /// The milliseconds left of the pause a rate-limited read started on the
  /// binding the retry refreshes; while above 0 the retry is disabled and shows the time left.
  final int pausedForMs;

  @override
  Widget build(BuildContext context) {
    final messages = cruftfreeRuntime.messages;
    final problem = failure is CruftFreeException ? (failure as CruftFreeException).problem : null;
    final worded = readFailureText(problem ?? ProblemDetails.decode(null, ProblemDetails.noResponseStatus, null), messages, site);
    return CruftFreeCallout(
      text: messages.key('framework.refreshFailed').text,
      detail: worded ?? (problem == null ? messages.key('framework.failed').text : problemTitleText(problem, messages)),
      icon: Icons.sync_problem,
      card: card,
      actions: [TextButton(onPressed: pausedForMs > 0 ? null : onRetry, child: Text(_retryText(pausedForMs, messages)))],
    );
  }
}

/// The pager over a paginated binding: the range caption ("Showing 26–50 of 340"),
/// previous, a numbered window of pages (`PagedBinding.window`, where `null` is an
/// ellipsis) and next, with a first-page and a last-page control around them when the
/// binding asks (`PagedBinding.firstLast`). It is named for assistive technology (`framework.pagination`),
/// each page button carries its number (`framework.pageNumber`) and the page shown is
/// marked selected. It shows once the binding has loaded at least [minimumPages] pages:
/// a table's footer from the first page, a data element's from the second.
class CruftFreePager extends StatelessWidget {
  const CruftFreePager({super.key, required this.binding, this.minimumPages = 2});

  final PagedBinding<Object?> binding;
  final int minimumPages;

  @override
  Widget build(BuildContext context) {
    final sizes = binding.pageSizes;
    if (!binding.isLoaded || (binding.pageCount < minimumPages && sizes.isEmpty)) {
      return const SizedBox.shrink();
    }
    final messages = cruftfreeRuntime.messages;
    final gap = CruftFreeTokens.of(context).gap;
    final range = binding.range;
    final current = binding.pageIndex + 1;
    final sizeLabel = messages.key('framework.pageSize').text;
    return Semantics(
      container: true,
      label: messages.key('framework.pagination').text,
      child: Wrap(
        alignment: WrapAlignment.end,
        crossAxisAlignment: WrapCrossAlignment.center,
        children: [
          if (range != null)
            Padding(
              padding: EdgeInsets.symmetric(horizontal: gap),
              child: Text(messages.key('framework.showingRangeOfTotal', {'from': range.from, 'to': range.to, 'total': range.total}).text),
            ),
          // The declared sizes the server accepts; choosing one requests it from the first page.
          if (sizes.isNotEmpty)
            Padding(
              padding: EdgeInsets.symmetric(horizontal: gap),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  ExcludeSemantics(child: Text(sizeLabel)),
                  SizedBox(width: gap / 2),
                  Semantics(
                    label: sizeLabel,
                    child: DropdownButton<int>(
                      value: sizes.contains(binding.pageSize) ? binding.pageSize : null,
                      items: [for (final size in sizes) DropdownMenuItem<int>(value: size, child: Text('$size'))],
                      onChanged: (size) {
                        if (size != null) {
                          binding.setPageSize(size);
                        }
                      },
                    ),
                  ),
                ],
              ),
            ),
          if (binding.firstLast) TextButton(onPressed: binding.hasPrevious ? binding.goToFirst : null, child: Text(messages.key('framework.firstPage').text)),
          TextButton(onPressed: binding.hasPrevious ? binding.previous : null, child: Text(messages.key('framework.previous').text)),
          for (final entry in binding.window)
            if (entry == null)
              ExcludeSemantics(
                child: Padding(
                  padding: EdgeInsets.symmetric(horizontal: gap / 2),
                  child: const Text('…'),
                ),
              )
            else
              Semantics(
                button: true,
                selected: entry == current,
                label: messages.key('framework.pageNumber', {'number': entry}).text,
                excludeSemantics: true,
                child: TextButton(onPressed: entry == current ? null : () => binding.goTo(entry - 1), child: Text('$entry')),
              ),
          TextButton(onPressed: binding.hasNext ? binding.next : null, child: Text(messages.key('framework.next').text)),
          if (binding.firstLast) TextButton(onPressed: binding.hasNext ? binding.goToLast : null, child: Text(messages.key('framework.lastPage').text)),
        ],
      ),
    );
  }
}

/// The derived empty state: the same parts as `emptyState` -- a soft icon
/// tile, the [title], the optional [description] and the optional [actions].
/// A [card]-sized one takes the surface of a card.
class CruftFreeEmptyState extends StatelessWidget {
  const CruftFreeEmptyState({super.key, required this.title, this.description, this.icon, this.actions = const [], this.card = false, this.style});

  final String title;
  final String? description;
  final IconData? icon;
  final List<Widget> actions;
  final bool card;
  final CruftFreeStyle? style;

  @override
  Widget build(BuildContext context) {
    final tokens = CruftFreeTokens.of(context);
    final theme = Theme.of(context);
    final glyph = icon;
    final more = description;
    final scale = cruftfreeFontScale(context, style);
    final body = Padding(
      padding: EdgeInsets.all(tokens.inset * 1.5),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.center,
        spacing: tokens.gap,
        children: [
          if (glyph != null)
            ExcludeSemantics(
              child: DecoratedBox(
                decoration: BoxDecoration(color: theme.colorScheme.surfaceContainerHighest, borderRadius: BorderRadius.circular(tokens.radius * 1.5)),
                child: SizedBox.square(
                  dimension: 48 * scale,
                  child: Icon(glyph, color: theme.colorScheme.onSurfaceVariant, size: cruftfreeScaledIconSize(context, scale)),
                ),
              ),
            ),
          Semantics(
            header: true,
            child: Text(
              title,
              textAlign: TextAlign.center,
              style: cruftfreeScaledPart(theme.textTheme.titleMedium, scale)?.copyWith(fontWeight: FontWeight.w600),
            ),
          ),
          if (more != null && more.isNotEmpty)
            Text(
              more,
              textAlign: TextAlign.center,
              style: cruftfreeScaledPart(theme.textTheme.bodyMedium, scale)?.copyWith(color: theme.colorScheme.onSurfaceVariant),
            ),
          if (actions.isNotEmpty) Wrap(alignment: WrapAlignment.center, spacing: tokens.gap, runSpacing: tokens.gap, children: actions),
        ],
      ),
    );
    final empty = Semantics(
      container: true,
      child: card ? Card(child: Center(child: body)) : Center(child: body),
    );
    return cruftfreeStyled(context, style, empty);
  }
}

/// `pageHeader(title, subtitle?) : back(Page)? { <actions> }`: a page's
