/// One bundled rendition of an image: its asset path and its width in pixels. A
/// [vector] rendition is an SVG, which has no pixel width and is drawn by `flutter_svg`.
class ImageVariant {
  const ImageVariant(this.asset, this.width, {this.vector = false});

  final String asset;
  final int width;
  final bool vector;
}

/// The rendition drawn into [availableWidth] logical pixels on a screen of
/// [pixelRatio] device pixels per logical pixel: the narrowest one at least as
/// wide as the space it fills, else the widest -- the choice a browser's
/// `srcset` makes, made explicitly. [variants] are narrowest first and not
/// empty; an unbounded space draws the widest.
ImageVariant pickImageVariant(List<ImageVariant> variants, double availableWidth, double pixelRatio) {
  if (availableWidth.isInfinite) {
    return variants.last;
  }
  final needed = availableWidth * pixelRatio;
  for (final variant in variants) {
    if (variant.width >= needed) {
      return variant;
    }
  }
  return variants.last;
}

final RegExp _safeAbsoluteImageUrl = RegExp(r'^https://[^/?#\\]', caseSensitive: false);

/// The address to draw for a URL that arrives as data (a gallery's `image:`, an
/// `image(url:)`): an https URL as it is, or a path appended to [apiBaseUrl].
/// Appending keeps the host [apiBaseUrl] names, so a value can change only the
/// path. Anything else shows no image. The one rule every client target holds.
String? cruftfreeSafeImageUrl(String? value, String apiBaseUrl) {
  final url = value?.trim() ?? '';
  if (_safeAbsoluteImageUrl.hasMatch(url)) {
    return url;
  }
  if (!url.startsWith('/') || url.startsWith('//') || url.contains(r'\')) {
    return null;
  }
  return '${apiBaseUrl.replaceFirst(RegExp(r'/+$'), '')}$url';
}

/// `image(url: value, alt?)`: an image address read from data, drawn only when
/// [cruftfreeSafeImageUrl] admits it on the API base -- anything else draws nothing.
/// Described to assistive technology only when it has a [semanticLabel].
class CruftFreeAddressImage extends StatelessWidget {
  const CruftFreeAddressImage({super.key, required this.address, this.semanticLabel, this.style});

  final String? address;
  final String? semanticLabel;
  final CruftFreeStyle? style;

  @override
  Widget build(BuildContext context) {
    final url = cruftfreeSafeImageUrl(address, cruftfreeRuntime.config.apiBaseUrl.toString());
    if (url == null) {
      return const SizedBox.shrink();
    }
    final label = semanticLabel;
    return cruftfreeStyled(context, style, Image.network(url, semanticLabel: label, excludeFromSemantics: label == null));
  }
}

/// A raster format's media type and the bytes that mark it, each at its offset.
typedef _ImageBytesSignature = ({String mediaType, List<({int offset, List<int> bytes})> parts});

/// The formats an `image(url: bytes)` draws, in the order they are tried.
const List<_ImageBytesSignature> _imageBytesSignatures = [
  (
    mediaType: 'image/png',
    parts: [
      (offset: 0, bytes: [137, 80, 78, 71, 13, 10, 26, 10]),
    ],
  ),
  (
    mediaType: 'image/jpeg',
    parts: [
      (offset: 0, bytes: [255, 216, 255]),
    ],
  ),
  (
    mediaType: 'image/gif',
    parts: [
      (offset: 0, bytes: [71, 73, 70, 56, 55, 97]),
    ],
  ),
  (
    mediaType: 'image/gif',
    parts: [
      (offset: 0, bytes: [71, 73, 70, 56, 57, 97]),
    ],
  ),
  (
    mediaType: 'image/webp',
    parts: [
      (offset: 0, bytes: [82, 73, 70, 70]),
      (offset: 8, bytes: [87, 69, 66, 80]),
    ],
  ),
];

/// The media type of the picture [data] holds, or `null` -- no picture -- for
/// bytes of any format the shared image-bytes rule does not name.
String? cruftfreeImageBytesType(List<int> data) {
  for (final signature in _imageBytesSignatures) {
    final matches = signature.parts.every((part) {
      if (data.length < part.offset + part.bytes.length) {
        return false;
      }
      for (var index = 0; index < part.bytes.length; index++) {
        if (data[part.offset + index] != part.bytes[index]) {
          return false;
        }
      }
      return true;
    });
    if (matches) {
      return signature.mediaType;
    }
  }
  return null;
}

/// `image(url: bytes, alt?)`: the picture's own bytes (a member of an installed
/// offline package, a `Bytes` field -- base64 on this client), drawn only when
/// [cruftfreeImageBytesType] names their format; any other bytes -- an SVG document, a
/// page -- draw nothing. Described to assistive technology only when it has a
/// [semanticLabel].
class CruftFreeBytesImage extends StatelessWidget {
  const CruftFreeBytesImage({super.key, required this.bytes, this.semanticLabel, this.style});

  final String? bytes;
  final String? semanticLabel;
  final CruftFreeStyle? style;

  @override
  Widget build(BuildContext context) {
    final encoded = bytes;
    final Uint8List data;
    try {
      data = encoded == null ? Uint8List(0) : base64Decode(encoded);
    } on FormatException {
      return const SizedBox.shrink();
    }
    if (cruftfreeImageBytesType(data) == null) {
      return const SizedBox.shrink();
    }
    final label = semanticLabel;
    final picture = Image.memory(data, gaplessPlayback: true, semanticLabel: label, excludeFromSemantics: label == null, errorBuilder: (context, error, stackTrace) => const SizedBox.shrink());
    return cruftfreeStyled(context, style, picture);
  }
}

/// `image(asset, alt?)`: one of the app's bundled images, drawn from the
/// smallest rendition that fills the space it is given. It keeps the intrinsic
/// aspect ratio so the layout does not shift as it loads, and is described to
/// assistive technology only when it has a [semanticLabel] -- without one it is
/// decorative.
class ResponsiveImage extends StatelessWidget {
  const ResponsiveImage({super.key, required this.variants, this.intrinsicWidth, this.intrinsicHeight, this.semanticLabel, this.style});

  final List<ImageVariant> variants;
  final int? intrinsicWidth;
  final int? intrinsicHeight;
  final String? semanticLabel;
  final CruftFreeStyle? style;

  @override
  Widget build(BuildContext context) {
    final pixelRatio = MediaQuery.devicePixelRatioOf(context);
    final label = semanticLabel;
    final picture = LayoutBuilder(
      builder: (context, constraints) {
        final variant = pickImageVariant(variants, constraints.maxWidth, pixelRatio);
        if (variant.vector) {
          return SvgPicture.asset(variant.asset, semanticsLabel: label, excludeFromSemantics: label == null);
        }
        return Image.asset(variant.asset, semanticLabel: label, excludeFromSemantics: label == null, gaplessPlayback: true);
      },
    );
    final width = intrinsicWidth;
    final height = intrinsicHeight;
    final sized = width == null || height == null ? picture : AspectRatio(aspectRatio: width / height, child: picture);
    return cruftfreeStyled(context, style, sized);
  }
}

/// `icon(name)`: a Material Symbols glyph, decorative -- a meaningful icon
/// is an `iconButton`, named by its message.
class CruftFreeIcon extends StatelessWidget {
  const CruftFreeIcon({super.key, required this.icon, this.style, this.paint});

  final IconData icon;
  final CruftFreeStyle? style;
  final CruftFreePaint? paint;

  @override
  Widget build(BuildContext context) => cruftfreeStyled(context, style, ExcludeSemantics(child: Icon(icon)), paint);
}

/// `avatar(initials?)`: a round avatar showing the initials, or a person
