/// `brand(label) { image(logo); }`: a round mark beside the label -- the
/// image when given, else the initials of the label. The mark is decorative:
/// the label names the brand. Written with a destination (`: to(Page)`, `: url(address)` or
/// `: configured(name)`) the whole brand is one link named by the label and running [onPressed].
class CruftFreeBrand extends StatelessWidget {
  const CruftFreeBrand({super.key, required this.label, this.image, this.initials, this.onPressed, this.style});

  final String label;
  final Widget? image;
  final String? initials;
  final VoidCallback? onPressed;
  final CruftFreeStyle? style;

  @override
  Widget build(BuildContext context) {
    final mark = image;
    final text = initials;
    final avatar = mark != null
        ? ClipOval(
            child: SizedBox.square(
              dimension: 40,
              child: FittedBox(fit: BoxFit.cover, child: mark),
            ),
          )
        : CircleAvatar(child: Text(text ?? ''));
    final brand = Row(
      mainAxisSize: MainAxisSize.min,
      spacing: CruftFreeTokens.of(context).gap,
      children: [
        ExcludeSemantics(child: avatar),
        Text(label, style: Theme.of(context).textTheme.titleMedium),
      ],
    );
    final target = onPressed;
    final content = target == null
        ? brand
        : _linkSurface(
            label: label,
            child: InkWell(onTap: target, child: brand),
          );
    return cruftfreeStyled(context, style, content);
  }
}

/// `sidebar { ... }`: the app shell's side rail. A layout scaffold lifts it
/// out of the body into its drawer or rail; used anywhere else it lays its
/// children out top to bottom.
class CruftFreeSidebarRegion extends StatelessWidget {
  const CruftFreeSidebarRegion({super.key, this.style, required this.children});

  final CruftFreeStyle? style;
  final List<Widget> children;

  @override
  Widget build(BuildContext context) {
    final column = Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, spacing: CruftFreeTokens.of(context).gap, children: children);
    return cruftfreeStyled(context, style, column);
  }
}

/// `topBar { ... }`: the app shell's top bar. A layout scaffold lifts it out
/// of the body into its app bar; used anywhere else it lays its children out
/// side by side.
/// With [fullWidth] its content runs edge to edge instead of on the content
/// column ([CruftFreeContentColumn]); the layout scaffold reads the flag.
class CruftFreeTopBarRegion extends StatelessWidget {
  const CruftFreeTopBarRegion({super.key, this.style, this.fullWidth = false, required this.children});

  final CruftFreeStyle? style;
  final bool fullWidth;
  final List<Widget> children;

  @override
  Widget build(BuildContext context) {
    final row = Row(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.center, spacing: CruftFreeTokens.of(context).gap, children: children);
    return cruftfreeStyled(context, style, row);
  }
}

/// The content column: [child] fills the width up to the theme's content
/// width (`size content`) and is centred beyond it -- the column the routed
/// page, a top bar and a footer share.
class CruftFreeContentColumn extends StatelessWidget {
  const CruftFreeContentColumn({super.key, required this.child});

  final Widget child;

  @override
  Widget build(BuildContext context) {
    return Align(
      alignment: AlignmentDirectional.topCenter,
      child: ConstrainedBox(
        constraints: BoxConstraints(maxWidth: CruftFreeTokens.of(context).contentWidth),
        child: child,
      ),
    );
  }
}

/// `footer { ... }`: the app shell's footer. It closes the scrolling page
/// (a layout writes it after its `slot`; its scrolling body, [CruftFreeLayoutBody],
/// rests it at the window's bottom while the page is shorter): a full-width surface under a
/// hairline, its children side by side wrapping onto the next run, on the
/// content column -- or edge to edge with [fullWidth]. It is the page's
/// content-information landmark.
class CruftFreeFooterRegion extends StatelessWidget {
  const CruftFreeFooterRegion({super.key, this.style, this.fullWidth = false, required this.children});

  final CruftFreeStyle? style;
  final bool fullWidth;
  final List<Widget> children;

  @override
  Widget build(BuildContext context) {
    final tokens = CruftFreeTokens.of(context);
    final scheme = Theme.of(context).colorScheme;
    final content = Padding(
      padding: EdgeInsets.symmetric(horizontal: tokens.inset, vertical: tokens.inset * 1.5),
      child: Wrap(spacing: tokens.gap * 2, runSpacing: tokens.gap, crossAxisAlignment: WrapCrossAlignment.center, children: children),
    );
    final band = DecoratedBox(
      decoration: BoxDecoration(
        color: scheme.surface,
        border: Border(top: BorderSide(color: scheme.outlineVariant)),
      ),
      child: SizedBox(
        width: double.infinity,
        child: fullWidth ? content : CruftFreeContentColumn(child: content),
      ),
    );
    return cruftfreeStyled(context, style, Semantics(container: true, explicitChildNodes: true, role: SemanticsRole.contentInfo, child: band));
  }
}

/// `stat(label, value, caption?) : icon(name)?, tone(t)?`: a tile -- the
/// label above a large figure and a muted [caption] -- announced together.
/// With an [icon] it sits in a rounded tile at the top-right, tinted by the
/// [tone] (the theme's primary by default); the tone never fills the tile.
/// A [paint] fills the tile's own surface and draws its outline.
class CruftFreeStat extends StatelessWidget {
  const CruftFreeStat({super.key, required this.label, required this.value, this.caption, this.icon, this.tone, this.style, this.paint});

  final String label;
  final String value;
  final String? caption;
  final IconData? icon;
  final String? tone;
  final CruftFreeStyle? style;
  final CruftFreePaint? paint;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final tokens = CruftFreeTokens.of(context);
    final textTheme = theme.textTheme;
    final glyph = icon;
    final note = caption;
    final accent = tone == null ? theme.colorScheme.primary : tokens.tone(tone!).background;
    final scale = cruftfreeFontScale(context, style);
    final figures = MergeSemantics(
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(label, style: cruftfreeScaledPart(textTheme.labelMedium, scale)?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
          Text(value, style: cruftfreeScaledPart(textTheme.headlineMedium, scale)?.copyWith(fontWeight: FontWeight.w600)),
          if (note != null && note.isNotEmpty) Text(note, style: cruftfreeScaledPart(textTheme.bodySmall, scale)?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
        ],
      ),
    );
    final tile = glyph == null
        ? null
        : ExcludeSemantics(
            child: DecoratedBox(
              decoration: BoxDecoration(color: accent.withValues(alpha: 0.12), borderRadius: BorderRadius.circular(tokens.radius)),
              child: SizedBox.square(
                dimension: 40 * scale,
                child: Icon(glyph, color: accent, size: cruftfreeScaledIconSize(context, scale)),
              ),
            ),
          );
    final painted = paint;
    final stat = Card(
      color: painted?.background,
      shape: cruftfreePaintedOutline(theme.cardTheme.shape, painted?.borderColor),
      child: Padding(
        padding: EdgeInsets.all(tokens.inset),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          spacing: tokens.gap,
          children: [
            Expanded(child: figures),
            ?tile,
          ],
        ),
      ),
    );
    return cruftfreeStyled(context, style, stat, painted?.drawnAround(outline: true));
  }
}

/// `progress(amount, maximum?) : tone(t)?`: a determinate bar filling [value] of [maximum]
/// (1 when unwritten), its fill in [tone]'s colour and its track the theme's.
class CruftFreeProgress extends StatelessWidget {
  const CruftFreeProgress({super.key, required this.value, this.maximum = 1, this.tone, this.style});

  final num value;
  final num maximum;
  final String? tone;
  final CruftFreeStyle? style;

  @override
  Widget build(BuildContext context) {
    final name = tone;
    final fill = name == null ? null : CruftFreeTokens.of(context).tone(name).background;
    return cruftfreeStyled(context, style, LinearProgressIndicator(value: cruftfreeProgressFill(value, maximum), color: fill));
  }
}

/// The share of its track a `progress` fills, by the rule every client target shares (a web
/// `<progress>` reads its `value` and `max` so): a maximum that is no positive number counts as
/// 1, and the amount is held to `0..maximum`, a non-finite one counting as 0.
double cruftfreeProgressFill(num value, num maximum) {
  final top = maximum.isFinite && maximum > 0 ? maximum.toDouble() : 1.0;
  final amount = value.isFinite ? value.toDouble().clamp(0.0, top) : 0.0;
  return amount / top;
}

/// A button's presentation (`kind(...)`).
enum CruftFreeButtonKind { standard, primary, secondary, link }

/// An action's label, led by its optional glyph (`icon(name)`).
Widget _actionLabel(BuildContext context, String label, IconData? icon) {
  final glyph = icon;
  if (glyph == null) {
    return Text(label);
  }
  return Row(
    mainAxisSize: MainAxisSize.min,
    spacing: CruftFreeTokens.of(context).gap / 2,
    children: [
      ExcludeSemantics(child: Icon(glyph, size: 20)),
      Text(label),
    ],
  );
}

/// What a link that opens a new tab adds to its name for assistive technology: the framework's
/// words (`framework.opensInNewTab`) in the visitor's language, read as the link's semantics hint.
String cruftfreeNewTabWords() => cruftfreeRuntime.messages.key('framework.opensInNewTab').text;

/// The words of a layout's skip link: the framework's string (`framework.skipToContent`) in the
/// visitor's language.
String cruftfreeSkipLinkWords() => cruftfreeRuntime.messages.key('framework.skipToContent').text;

/// The small glyph after the label of a link that opens a new tab: drawn while the theme keeps
/// `flag newTabGlyph`, and never read out (the words above name the link either way).
Widget? cruftfreeNewTabGlyph(BuildContext context) => CruftFreeTokens.of(context).newTabGlyph ? const ExcludeSemantics(child: Icon(Icons.open_in_new, size: 16)) : null;

/// [label] followed by the glyph of a link that opens a new tab, when the theme draws one.
Widget _withNewTabGlyph(BuildContext context, Widget label, {required bool opensNewTab}) {
  final glyph = opensNewTab ? cruftfreeNewTabGlyph(context) : null;
  if (glyph == null) {
    return label;
  }
  return Row(mainAxisSize: MainAxisSize.min, spacing: CruftFreeTokens.of(context).gap / 2, children: [label, glyph]);
}

/// An action's label led by its busy indicator in place of its glyph.
Widget _busyLabel(BuildContext context, String label) {
  return Row(mainAxisSize: MainAxisSize.min, spacing: CruftFreeTokens.of(context).gap / 2, children: [_busyIndicator(context), Text(label)]);
}

/// The busy indicator of an action whose work is running (`busy(c)`): a ring that takes the place
/// of the action's glyph, named by the loading caption. Under a reduced-motion preference the
/// ring is drawn still (a quarter arc) instead of turning.
Widget _busyIndicator(BuildContext context) {
  final caption = cruftfreeRuntime.messages.key('framework.loading').text;
  final still = MediaQuery.disableAnimationsOf(context);
  return SizedBox(
    width: 20,
    height: 20,
    child: CircularProgressIndicator(strokeWidth: 2, value: still ? 0.25 : null, semanticsLabel: caption),
  );
}

/// A busy action ignores activation but, unlike a disabled one, stays focusable and enabled.
void _ignoreActivation() {}

/// `button(label) : onClick(...), kind(k)?, tone(t)?, icon(name)?, disabled(c)?, busy(c)?`: a
/// button; without a handler, or while [enabled] is false, it is shown disabled. While [busy] its
/// glyph gives way to a busy indicator and it ignores activation.
class CruftFreeButton extends StatelessWidget {
  const CruftFreeButton({super.key, required this.label, this.kind = CruftFreeButtonKind.standard, this.tone, this.icon, this.onPressed, this.enabled = true, this.busy = false, this.autofocus = false, this.style});

  final String label;
  final CruftFreeButtonKind kind;
  final String? tone;
  final IconData? icon;
  final VoidCallback? onPressed;
  final bool enabled;
  final bool busy;

  /// `initialFocus`: has focus when the route that shows it opens.
  final bool autofocus;
  final CruftFreeStyle? style;

  @override
  Widget build(BuildContext context) {
    final toneName = tone;
    final colors = toneName == null ? null : CruftFreeTokens.of(context).tone(toneName);
    final buttonStyle = colors == null ? null : ButtonStyle(backgroundColor: WidgetStatePropertyAll(colors.background), foregroundColor: WidgetStatePropertyAll(colors.foreground));
    final child = busy ? _busyLabel(context, label) : _actionLabel(context, label, icon);
    final available = enabled ? onPressed : null;
    final pressed = busy && available != null ? _ignoreActivation : available;
    final button = switch (kind) {
      CruftFreeButtonKind.primary => FilledButton(onPressed: pressed, style: buttonStyle, autofocus: autofocus, child: child),
      CruftFreeButtonKind.standard => FilledButton.tonal(onPressed: pressed, style: buttonStyle, autofocus: autofocus, child: child),
      CruftFreeButtonKind.secondary => OutlinedButton(onPressed: pressed, style: buttonStyle, autofocus: autofocus, child: child),
      CruftFreeButtonKind.link => TextButton(onPressed: pressed, style: buttonStyle, autofocus: autofocus, child: child),
    };
    return cruftfreeStyled(context, style, button);
  }
}

/// `iconButton(icon, label) : hint(text)?, disabled(c)?, busy(c)?`: an icon-only action, named by
/// its label. Its tooltip is the label, followed by the [hint] when there is one. While [busy] its
/// glyph gives way to a busy indicator and it ignores activation.
class CruftFreeIconButton extends StatelessWidget {
  const CruftFreeIconButton({super.key, required this.icon, required this.label, this.hint, this.onPressed, this.enabled = true, this.busy = false, this.autofocus = false, this.style});

  final IconData icon;
  final String label;
  final String? hint;
  final VoidCallback? onPressed;
  final bool enabled;
  final bool busy;

  /// `initialFocus`: has focus when the route that shows it opens.
  final bool autofocus;
  final CruftFreeStyle? style;

  @override
  Widget build(BuildContext context) {
    final description = hint;
    final tooltip = description == null || description.isEmpty ? label : '$label: $description';
    final available = enabled ? onPressed : null;
    final pressed = busy && available != null ? _ignoreActivation : available;
    return cruftfreeStyled(context, style, IconButton(icon: busy ? _busyIndicator(context) : Icon(icon), tooltip: tooltip, onPressed: pressed, autofocus: autofocus));
  }
}

/// `link(label, Page, ...) : kind(k)?, icon(name)?, disabled(c)?`: navigates to its page;
/// announced as a link. While [enabled] is false it navigates nowhere and is announced as
/// unavailable. An `externalLink` written with `newTab` is a link that [opensNewTab]: its
/// semantics hint says so, and a glyph follows its label while the theme draws one.
class CruftFreeLink extends StatelessWidget {
  const CruftFreeLink({super.key, required this.label, required this.onPressed, this.kind = CruftFreeButtonKind.link, this.icon, this.enabled = true, this.autofocus = false, this.opensNewTab = false, this.style});

  final String label;
  final VoidCallback onPressed;
  final CruftFreeButtonKind kind;
  final IconData? icon;
  final bool enabled;

  /// The link opens a new tab (`externalLink : newTab`).
  final bool opensNewTab;

  /// `initialFocus`: has focus when the route that shows it opens.
  final bool autofocus;
  final CruftFreeStyle? style;

  @override
  Widget build(BuildContext context) {
    final child = _withNewTabGlyph(context, _actionLabel(context, label, icon), opensNewTab: opensNewTab);
    final pressed = enabled ? onPressed : null;
    final button = switch (kind) {
      CruftFreeButtonKind.primary => FilledButton(onPressed: pressed, autofocus: autofocus, child: child),
      CruftFreeButtonKind.standard => FilledButton.tonal(onPressed: pressed, autofocus: autofocus, child: child),
      CruftFreeButtonKind.secondary => OutlinedButton(onPressed: pressed, autofocus: autofocus, child: child),
      CruftFreeButtonKind.link => TextButton(onPressed: pressed, autofocus: autofocus, child: child),
    };
    return cruftfreeStyled(context, style, Semantics(link: true, hint: opensNewTab ? cruftfreeNewTabWords() : null, child: button));
  }
}

/// The height of a table's heading row when neither the table nor the theme sets one: the
/// Material Design heading row height [DataTable] documents.
const double _tableHeadingHeight = 56;

/// A table that fills the width it is given, and scrolls sideways when its columns need more.
/// Inside a capped `scroll` its heading row stays in view while its rows scroll beneath it.
class CruftFreeTableSurface extends StatelessWidget {
  const CruftFreeTableSurface({super.key, required this.table});

  final DataTable table;

  @override
  Widget build(BuildContext context) {
    final theme = DataTableTheme.of(context);
    final heading = table.headingRowHeight ?? theme.headingRowHeight ?? _tableHeadingHeight;
    // The heading height every rendering of this table lays out with, stated once, so the copy
    // kept in view is clipped exactly to the heading row.
    return DataTableTheme(
      data: theme.copyWith(headingRowHeight: heading),
      child: _CruftFreeCappedScroll.holds(context) ? _CruftFreePinnedHeadingTable(table: table, heading: heading) : _sideways(table, null),
    );
  }
}

/// [table] filling the width it is given and scrolling sideways, with [pinned] -- the copy of
/// its heading kept in view -- over it.
Widget _sideways(Widget table, Widget? pinned) {
  return LayoutBuilder(
    builder: (context, constraints) => SingleChildScrollView(
      scrollDirection: Axis.horizontal,
      child: ConstrainedBox(
        constraints: BoxConstraints(minWidth: constraints.hasBoundedWidth ? constraints.maxWidth : 0),
        child: pinned == null ? table : Stack(fit: StackFit.passthrough, children: [table, pinned]),
      ),
    ),
  );
}

/// A table inside a capped `scroll` whose heading row stays at the top of the region while the
/// rows scroll beneath it. It listens to the region's vertical [Scrollable] and, once the table's
/// top has scrolled above the region's top, draws over the table a copy of it clipped to the
/// heading row, at the region's top (never below the table's last row). The copy is the same
/// table laid out at the same width, so its columns line up with the rows; it takes no part in
/// focus or assistive technology, where the table's own heading row stands, and a tap on a
/// sortable heading in it sorts as the heading does.
class _CruftFreePinnedHeadingTable extends StatefulWidget {
  const _CruftFreePinnedHeadingTable({required this.table, required this.heading});

  final DataTable table;
  final double heading;

  @override
  State<_CruftFreePinnedHeadingTable> createState() => _CruftFreePinnedHeadingTableState();
}

class _CruftFreePinnedHeadingTableState extends State<_CruftFreePinnedHeadingTable> {
  ScrollPosition? _position;
  double _offset = 0;

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final position = Scrollable.maybeOf(context, axis: Axis.vertical)?.position;
    if (!identical(position, _position)) {
      _position?.removeListener(_follow);
      _position = position;
      _position?.addListener(_follow);
    }
    WidgetsBinding.instance.addPostFrameCallback((_) => _follow());
  }

  /// How far the table's top has scrolled above the region's top, limited so the copy never
  /// leaves the table; 0 while the table's own heading is in view.
  double _measure() {
    final box = context.findRenderObject();
    final viewport = Scrollable.maybeOf(context, axis: Axis.vertical)?.context.findRenderObject();
    if (box is! RenderBox || !box.attached || !box.hasSize || viewport is! RenderBox || !viewport.attached) {
      return 0;
    }
    final above = -box.localToGlobal(Offset.zero, ancestor: viewport).dy;
    return above.clamp(0, math.max(0, box.size.height - widget.heading)).toDouble();
  }

  void _follow() {
    if (!mounted) {
      return;
    }
    final offset = _measure();
    if (offset != _offset) {
      setState(() => _offset = offset);
    }
  }

  @override
  void dispose() {
    _position?.removeListener(_follow);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final pinned = _offset <= 0
        ? null
        : Positioned(
            top: _offset,
            left: 0,
            right: 0,
            height: widget.heading,
            child: ExcludeSemantics(
              child: ExcludeFocus(
                child: ClipRect(
                  child: ColoredBox(
                    color: Theme.of(context).colorScheme.surface,
                    child: OverflowBox(alignment: AlignmentDirectional.topStart, minHeight: 0, maxHeight: double.infinity, child: widget.table),
                  ),
                ),
              ),
            ),
          );
    return _sideways(widget.table, pinned);
  }
}

/// `hint(text)` on an element: [message] shown as a tooltip while the pointer rests on [child] or
/// the keyboard focuses it, and read by assistive technology as its description. A `null` or
/// empty [message] shows no hint.
class CruftFreeHint extends StatefulWidget {
  const CruftFreeHint({super.key, required this.message, required this.child});

  final String? message;
  final Widget child;

  @override
  State<CruftFreeHint> createState() => _CruftFreeHintState();
}

class _CruftFreeHintState extends State<CruftFreeHint> {
  final GlobalKey<TooltipState> _tooltip = GlobalKey<TooltipState>();

  void _focusChanged(bool focused) {
    if (focused) {
      _tooltip.currentState?.ensureTooltipVisible();
    } else {
      Tooltip.dismissAllToolTips();
    }
  }

  @override
  Widget build(BuildContext context) {
    final message = widget.message;
    if (message == null || message.isEmpty) {
      return widget.child;
    }
    return Tooltip(
      key: _tooltip,
      message: message,
      child: Focus(canRequestFocus: false, skipTraversal: true, onFocusChange: _focusChanged, child: widget.child),
    );
  }
}
